    o: ['[\'Can\'] [\'Ali\', \'Ece\'] [\'Ada\', \'Ali\', \'Can\', \'Ece\']', '[\'Can\'] [\'Ada\', \'Ali\', \'Ece\'] [\'Ada\', \'Ali\', \'Ece\']', '[\'Can\'] [\'Ali\', \'Ece\'] [\'Ada\', \'Ali\', \'Ece\']', '[\'Ada\', \'Ali\', \'Can\', \'Ece\'] [\'Ali\', \'Ece\'] [\'Can\']'],
